INSERT INTO public.jobs (id, title, company_id, company_name, company_logo, location, salary_range, job_type, experience_level, description, requirements, skills_required, status, is_suspicious, suspicious_reason, created_at) VALUES
('job-1', 'Senior Fullstack TypeScript Engineer', 'co-1', 'Google Cloud Platform', 'https://images.unsplash.com/photo-1614741118887-7a4ee193a5fa?w=100&auto=format&fit=crop&q=60', 'Remote (APAC)', '$8,000 - $13,000 / month', 'Remote', 'Senior Level', 'We are looking for a remote developer to build high-scale cloud platforms using React, Node.js, and server-side TypeScript. In this role, you will implement modular microservices and real-time collaboration engines.', ARRAY['5+ years programming experience in React and Node.js', 'Proven expertise with modern build systems and bundlers (Vite/Rspack)', 'Excellent system design capability and database performance optimization skills']::text[], ARRAY['React', 'TypeScript', 'Node.js', 'Vite', 'PostgreSQL', 'Tailwind CSS']::text[], 'approved', false, NULL, '2026-05-17T23:35:24.530Z'),
('job-2', 'Frontend Developer (React & Tailwind)', 'co-2', 'Finverge Labs', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=100&auto=format&fit=crop&q=60', 'Singapore / Hybrid', '$4,500 - $6,000 / month', 'Full-time', 'Mid Level', 'Join Finverge to design and build transactional web dashboards for multi-asset wallets and ledger analytics. You will work in a fast-paced environment with a core stack of React 19, Tailwind CSS, and Framer Motion.', ARRAY['3+ years experience with React Hook form optimization', 'Demonstrated high visual styling fidelity with Tailwind CSS', 'Knowledge of state management such as Zustand or React Context']::text[], ARRAY['React', 'Tailwind CSS', 'Framer Motion', 'Zustand', 'CSS']::text[], 'approved', false, NULL, '2026-05-20T11:35:24.530Z'),
('job-3', 'Urgent Remote Assistant - Weekly High Pay Payout', 'co-4', 'CryptoApex Global Inc.', 'https://images.unsplash.com/photo-1518186285589-2f7649de83e0?w=100&auto=format&fit=crop&q=60', 'Offshore Office / Immediate Start', '$1,000 - $2,500 / week', 'Part-time', 'Entry Level', 'Immediate hiring for virtual marketing assistants. No prior skillset is required! Training fee of $50 must be wired to our platform wallet to unlock premium task dashboard instructions. High commission payouts daily.', ARRAY['Must have stable internet and a bank account', 'Willing to pay $50 training/tooling unlock package up front', 'Work only 1 hour per day and earn thousands']::text[], ARRAY['Marketing', 'Data Entry', 'Telegram']::text[], 'pending', true, 'Requires upfront payment ($50 training fee) to unlock working portal, promises unrealistically high entry-level compensation with no skill requirements, and operates via suspect offshore billing patterns.', '2026-05-20T15:35:24.530Z'),
('job-4', 'Software Engineer - Backend Go & gRPC', 'co-6', 'GoTo Group', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 18.000.000 - Rp 30.000.000 / month', 'Full-time', 'Mid Level', 'Kami sedang mencari Backend Go Developer untuk mengoptimalkan layanan on-demand kami, merawat request throughput tinggi, gRPC api endpoints, dan database SQL/NoSQL berskala besar.', ARRAY['2+ tahun pengalaman kerja dengan Golang', 'Memahami REST API, gRPC, serta protocol buffers', 'Berpengalaman dengan relational database seperti PostgreSQL dan message broker seperti Kafka']::text[], ARRAY['Go', 'gRPC', 'PostgreSQL', 'Kafka', 'Redis', 'Docker']::text[], 'approved', false, NULL, '2026-05-18T23:35:24.530Z'),
('job-5', 'Senior Frontend Engineer (React/NextJS)', 'co-5', 'Tokopedia', 'https://images.unsplash.com/photo-1563013544-824ae1d704d3?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID / Hybrid', 'Rp 25.000.000 - Rp 45.000.000 / month', 'Full-time', 'Senior Level', 'Pimpin pengembangan arsitektur website pembeli Tokopedia menggunakan Next.js dan optimasi Core Web Vitals untuk meningkatkan konversi pengguna dan performa SEO.', ARRAY['5+ tahun pengalaman dalam ekosistem frontend JavaScript', 'Keahlian mendalam mengenai SSR, SSG, heritansi modul Next.js, dan optimasi CSS', 'Leadership yang matang untuk mentoring junior developers']::text[], ARRAY['React', 'Next.js', 'TypeScript', 'Tailwind CSS', 'GraphQL', 'Lighthouse']::text[], 'approved', false, NULL, '2026-05-20T03:35:24.530Z'),
('job-6', 'Mobile Developer - Flutter', 'co-7', 'Traveloka', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 14.000.000 - Rp 22.000.000 / month', 'Full-time', 'Mid Level', 'Membangun fungsionalitas pencarian hotel dan pemesanan aktivitas tiket liburan secara dinamis menggunakan Flutter untuk platform Android dan iOS.', ARRAY['Minimal 2 tahun pengalaman komparatif menggunakan Flutter dan Dart', 'Familiar dengan state management Bloc atau Provider', 'Pernah merilis minimal 1 aplikasi ke Play Store atau App Store']::text[], ARRAY['Flutter', 'Dart', 'Android', 'iOS', 'Bloc', 'REST API']::text[], 'approved', false, NULL, '2026-05-20T23:35:24.530Z'),
('job-7', 'Junior Data Analyst', 'co-3', 'Veritas Analytics', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 7.500.000 - Rp 11.000.000 / month', 'Full-time', 'Entry Level', 'Melakukan pembersihan data mentah, mengekstrak metrik performa operasional berkala, serta menyusun dashboard visualisasi menggunakan Tableau atau PowerBI.', ARRAY['Pendidikan minimal S1 Statistika, Matematika, atau Sistem Informasi', 'Lancer dalam menulis query SQL kompleks (JOIN, Subqueries, CTEs)', 'Familiaritas dasar berkomunikasi statistik dalam bahasa Python atau R']::text[], ARRAY['SQL', 'Python', 'Tableau', 'Excel', 'Pandas']::text[], 'approved', false, NULL, '2026-05-20T05:35:24.530Z'),
('job-8', 'Cloud DevOps Practitioner', 'co-6', 'GoTo Group', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=100&auto=format&fit=crop&q=60', 'Remote (Indonesia)', 'Rp 22.000.000 - Rp 38.000.000 / month', 'Remote', 'Senior Level', 'Bertanggung jawab atas otomatisasi pipeline CI/CD, mengawasi klaster orkestrasi Kubernetes di Google Cloud, serta memantau keandalan sistem berskala jutaan user.', ARRAY['Pemahaman luar biasa tentang Terraform, Ansible, dan Docker', 'Sertifikasi GCP Professional Cloud Architect lebih disukai', 'Terbiasa dengan monitoring tools seperti Prometheus dan Grafana']::text[], ARRAY['Kubernetes', 'Docker', 'Terraform', 'GCP', 'GitHub Actions', 'Prometheus']::text[], 'approved', false, NULL, '2026-05-20T18:35:24.530Z'),
('job-9', 'Web Developer (PHP & Laravel)', 'co-10', 'Bukalapak', 'https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=100&auto=format&fit=crop&q=60', 'Bandung, ID / Remote', 'Rp 10.000.000 - Rp 16.000.000 / month', 'Full-time', 'Mid Level', 'Mengembangkan sistem operasional merchant dan inventori logistik penunjang warung-warung menggunakan framework Laravel 11 terintegrasi.', ARRAY['Paham OOP PHP dengan baik dan standar kepatuhan PSR', 'Minimal 2 tahun pengalaman aktif memproduksi modul fungsional di Laravel', 'Terbiasa dengan database MySQL/MariaDB dan integrasi REST backend']::text[], ARRAY['PHP', 'Laravel', 'MySQL', 'JavaScript', 'HTML', 'Git']::text[], 'approved', false, NULL, '2026-05-17T23:35:24.530Z'),
('job-10', 'UI/UX Designer Expert', 'co-11', 'Vidio', 'https://images.unsplash.com/photo-1522869635100-9f4c5e86aa37?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 12.000.000 - Rp 20.000.000 / month', 'Full-time', 'Mid Level', 'Merancang wireframe, user flow interaktif, serta visual aset modern untuk platform streaming video kami di Web, Mobile App, dan Smart TV web kit.', ARRAY['Portofolio desain UI/UX solid di Figma atau Sketch', 'Mahir melakukan user research dan usability testing pada produk hiburan digital', 'Memahami basic CSS/HTML untuk koordinasi lancar dengan frontend developers']::text[], ARRAY['Figma', 'UI Design', 'Wireframing', 'User Research', 'Prototyping']::text[], 'approved', false, NULL, '2026-05-14T17:35:24.530Z'),
('job-11', 'IT Corporate Security Lead', 'co-8', 'Bank Mandiri', 'https://images.unsplash.com/photo-1559526324-4b87b5e36e44?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 30.000.000 - Rp 50.000.000 / month', 'Full-time', 'Senior Level', 'Mengawasi audit postur keamanan jaringan, kepatuhan infrastruktur perbankan digital Mandiri, serta mengamankan gateway transaksi keuangan dari eksploitasi siber.', ARRAY['Pendidikan S1 Informatika keamanan siber atau kompetensi setara', 'Sertifikasi Certified Information Systems Auditor (CISA) atau CISSP', 'Berpengalaman dengan regulasi perbankan OJK dan kepatuhan ISO 27001']::text[], ARRAY['Cybersecurity', 'Risk Assessment', 'ISO 27001', 'Network Auditing', 'Firewalls']::text[], 'approved', false, NULL, '2026-05-10T23:35:24.530Z'),
('job-12', 'Mobile Developer React Native', 'co-9', 'Shopee Indonesia', 'https://images.unsplash.com/photo-1472851294608-062f824d296e?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID / Hybrid', 'Rp 16.000.000 - Rp 27.000.000 / month', 'Full-time', 'Mid Level', 'Bergabunglah di tim inti Shopee Pay untuk memoles komponen interface pembayaran e-wallet menggunakan React Native dengan optimalisasi runtime memory rendering.', ARRAY['Keahlian mendalam dalam TypeScript dan React Native Native Bridges', 'Familiar dengan Redux Saga atau Toolkit untuk state synchronisation', 'Kemampuan andal mematangkan visual layout responsif multi-device screen']::text[], ARRAY['React Native', 'TypeScript', 'Redux', 'iOS', 'Android', 'Jest']::text[], 'approved', false, NULL, '2026-05-19T17:35:24.530Z'),
('job-13', 'Android Developer (Java/Kotlin)', 'co-5', 'Tokopedia', 'https://images.unsplash.com/photo-1563013544-824ae1d704d3?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 15.000.000 - Rp 25.000.000 / month', 'Full-time', 'Mid Level', 'Ciptakan fitur interaksi produk instan, ulasan gambar, serta tracking ekspedisi logistik kurir real-time pada aplikasi native Android Tokopedia.', ARRAY['Minimal 3 tahun mengemban development native Android Kotlin', 'Memahami Android Jetpack Components dan pola arsitektur MVVM', 'Terbiasa melakukan profiling memori menggunakan Android Studio tools']::text[], ARRAY['Kotlin', 'Android SDK', 'Java', 'MVVM', 'Retrofit', 'Coroutines']::text[], 'approved', false, NULL, '2026-05-20T09:35:24.530Z'),
('job-14', 'iOS Platform Engineer', 'co-6', 'GoTo Group', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 18.000.000 - Rp 32.000.000 / month', 'Full-time', 'Senior Level', 'Pahat kode tangguh untuk aplikasi Gojek pelanggan di ekosistem iOS menggunakan Swift modern, SwiftUI, serta struktur concurrency modern (async/await).', ARRAY['4+ tahun menulis program iOS native komersial', 'Pemahaman kuat atas memory leaks management (retain cycles, ARC)', 'Pengalaman rilis TestFlight dan App Store submission']::text[], ARRAY['Swift', 'SwiftUI', 'XCode', 'Combine', 'iOS SDK', 'Cocoapods']::text[], 'approved', false, NULL, '2026-05-16T19:35:24.530Z'),
('job-15', 'Machine Learning Deep Learning Specialist', 'co-3', 'Veritas Analytics', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=100&auto=format&fit=crop&q=60', 'Remote (Indonesia)', 'Rp 20.000.000 - Rp 35.000.000 / month', 'Remote', 'Senior Level', 'Latih model prediksi risiko kredit perbankan, deteksi fraud transaksi keuangan, serta model NLP teks berkas dengan Python, PyTorch, dan Docker.', ARRAY['Gelar S2/S3 bidang Ilmu Komputer, Matematika, Data Science atau setara', 'Pengalaman hands-on melatih model deep learning dan machine learning klasik', 'Keahlian mumpuni memicu deployment model ke AWS SageMaker atau GCP Vertex AI']::text[], ARRAY['Python', 'PyTorch', 'TensorFlow', 'Scikit-Learn', 'Docker', 'Machine Learning']::text[], 'approved', false, NULL, '2026-05-20T19:35:24.530Z'),
('job-16', 'Cloud Solutions Architect', 'co-1', 'Google Cloud Platform', 'https://images.unsplash.com/photo-1614741118887-7a4ee193a5fa?w=100&auto=format&fit=crop&q=60', 'Singapore / Jakarta (Hybrid)', '$6,500 - $11,000 / month', 'Full-time', 'Senior Level', 'Help global tier-1 enterprise clients architecture secure, reliable, and scalable applications over GCP platform infrastructure, focusing on serverless migrations.', ARRAY['8+ years cloud implementation consulting experience', 'Active GCP Professional Cloud Security or Solutions Architect Certification', 'Highly technical in complex networking topology, Kubernetes cluster federations, and IAM setups']::text[], ARRAY['GCP', 'Cloud Architecture', 'Terraform', 'Kubernetes', 'BGP', 'IAM']::text[], 'approved', false, NULL, '2026-05-15T23:35:24.530Z'),
('job-17', 'Fullstack Laravel Developer (Kopi Kenangan App)', 'co-12', 'Kopi Kenangan', 'https://images.unsplash.com/photo-1541167760496-1628856ab772?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 11.000.000 - Rp 18.000.000 / month', 'Full-time', 'Mid Level', 'Mengembangkan sistem loyalty member, digital vouchers order backend, serta integrasi pemesanan point of sales (POS) Kopi Kenangan seluruh Indonesia.', ARRAY['Minimal 3 tahun berkecimpung mengembangkan Fullstack PHP Laravel dan VueJS', 'Pengalaman matang integrasi payment gateway MIDTRANS atau XENDIT', 'Familiar dengan Redis queue worker untuk asynchronous transactional jobs']::text[], ARRAY['Laravel', 'Vue.js', 'PHP', 'Midtrans', 'Redis', 'MySQL']::text[], 'approved', false, NULL, '2026-05-16T23:35:24.530Z'),
