('job-19', 'Lead Product Manager - Core Transactions', 'co-5', 'Tokopedia', 'https://images.unsplash.com/photo-1563013544-824ae1d704d3?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID', 'Rp 30.000.000 - Rp 52.000.000 / month', 'Full-time', 'Senior Level', 'Nakhodai visi produk, strategi rilis, serta kordinasi lintas fungsional (Engineering, Business, Design) untuk checkout cart core Tokopedia merchant transactions.', ARRAY['5+ tahun rekam jejak sukses sebagai Product Manager di sektor Fintech / E-commerce', 'Kemampuan analitis data (SQL, Google Analytics, Amplitude) tingkat lanjut', 'Komunikasi diplomatis andal melobi business requirements menjadi functional design']::text[], ARRAY['Product Strategy', 'Amplitude', 'SQL', 'Agile', 'User Research', 'Wireframes']::text[], 'approved', false, NULL, '2026-05-20T07:35:24.530Z'),
('job-20', 'Database Administrator DBA Specialist', 'co-8', 'Bank Mandiri', 'https://images.unsplash.com/photo-1559526324-4b87b5e36e44?w=100&auto=format&fit=crop&q=60', 'Jakarta, ID / On-site', 'Rp 14.000.000 - Rp 23.000.000 / month', 'Full-time', 'Mid Level', 'Bertanggung jawab melakukan backup database Mandiri, replikasi data high-availability, optimasi query lambat, serta instalasi patch keamanan Oracle/Postgres db.', ARRAY['S1 Teknik Informatika/Sistem Informasi', 'Menguasai setup server Oracle Database, Microsoft SQL Server, atau PostgreSQL', 'Memahami arsitektur failover cluster, partisi tabel besar, serta optimasi indeks']::text[], ARRAY['Oracle DB', 'PostgreSQL', 'SQL Server', 'Database Indexing', 'Backup & Recovery']::text[], 'approved', false, NULL, '2026-05-17T15:35:24.530Z'),
('job-21', 'Frontend Developer (Angular / Vue)', 'co-2', 'Finverge Labs', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=100&auto=format&fit=crop&q=60', 'Singapore / Hybrid', '$4,000 - $6,500 / month', 'Contract', 'Mid Level', 'Contract base developer to collaborate with back office ledger migration dashboard UI using Angular 17. Maintain high performance grid rendering.', ARRAY['At least 3 years commercial Angular experience', 'Great implementation of RXJS, state management, and unit testing using Jasmine/Karma', 'Fluency in English team discussions is mandatory']::text[], ARRAY['Angular', 'RxJS', 'TypeScript', 'Karma', 'Ngrx', 'Tailwind CSS']::text[], 'approved', false, NULL, '2026-05-16T09:35:24.530Z'),
