-- ==============================================
-- DATA SEED UNTUK SUPABASE
-- FORMAT SPECIAL: UNTUK KOLOM BERTYPE text[]
-- ==============================================
-- Jalankan file ini jika tipe kolom requirements & skills_required Anda adalah text[]
-- ==============================================

-- 1. SEED COMPANIES
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, logo = EXCLUDED.logo, description = EXCLUDED.description, industry = EXCLUDED.industry, location = EXCLUDED.location, website = EXCLUDED.website, is_verified = EXCLUDED.is_verified;


-- 2. SEED JOBS (DENGAN FORMAT ARRAY pg)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, company_id = EXCLUDED.company_id, company_name = EXCLUDED.company_name, company_logo = EXCLUDED.company_logo, location = EXCLUDED.location, salary_range = EXCLUDED.salary_range, job_type = EXCLUDED.job_type, experience_level = EXCLUDED.experience_level, description = EXCLUDED.description, requirements = EXCLUDED.requirements, skills_required = EXCLUDED.skills_required, status = EXCLUDED.status, is_suspicious = EXCLUDED.is_suspicious, suspicious_reason = EXCLUDED.suspicious_reason, created_at = EXCLUDED.created_at;
